const { createServer } = await import('node:http');
const timers = new Set();
let requests = 0;
const server = createServer((req, res) => { requests += 1;
if (requests === 1) { res.statusCode = 503; res.write('discard'); }
else res.end('{"id":"after-cancel","score":6}');
});
await new Promise((resolve, reject) => { server.once('error', reject); server.listen(0, '127.0.0.1', resolve); });
const url = 'http://127.0.0.1:' + server.address().port + '/record';
try {
let cancelledBodies = 0;
let resolveClosed;
const closed = new Promise(resolve => { resolveClosed = resolve; });
server.on('request', (_request, response) => {
  if (response.statusCode === 503) response.once('close', () => { cancelledBodies += 1; resolveClosed(); });
});
const result = await submission.fetchRecord(url, { timeoutMs: 1200, backoffMs: 0 });
let guard;
try { await Promise.race([closed, new Promise(resolve => { guard = setTimeout(resolve, 400); })]); }
finally { clearTimeout(guard); }
observe({ result, requests, cancelledBodies });
} finally {
  for (const timer of timers) clearTimeout(timer);
  server.closeAllConnections();
  await new Promise((resolve, reject) => server.close(error => error ? reject(error) : resolve()));
}
